# Define the CNN model architecture
class BirdCLEFModel(nn.Module):
    def __init__(self, num_species):
        super(BirdCLEFModel, self).__init__()
        
        # Convolutional layers with BatchNorm and ReLU
        conv_layers = []
        in_channels = 1
        out_channels = [32, 64, 128] if NUM_CONV_LAYERS == 3 else [32, 64]
        
        for i in range(NUM_CONV_LAYERS):
            conv_layers.append(nn.Conv2d(in_channels, out_channels[i], kernel_size=3, padding=1))
            conv_layers.append(nn.BatchNorm2d(out_channels[i]))
            conv_layers.append(nn.ReLU())
            in_channels = out_channels[i]
        
        self.conv_layers = nn.Sequential(*conv_layers)
        
        # Adaptive pooling and flattening
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        
        # Classifier with dropout and linear layers
        self.classifier = nn.Sequential(
            nn.Linear(out_channels[-1], 128),
            nn.ReLU(),
            nn.Dropout(DROPOUT_RATE),
            nn.Linear(128, num_species)
        )
    
    def forward(self, x):
        x = self.conv_layers(x)
        x = self.pool(x).view(x.size(0), -1)
        return torch.sigmoid(self.classifier(x))

